const source = $json.body ?? $json;
if (!source.missionId || !source.taskId || !source.actorInput || !source.callbackUrl) {
  throw new Error('missionId, taskId, actorInput e callbackUrl são obrigatórios.');
}
const supported = ['b2b_prospecting', 'market_radar', 'price_monitoring'];
if (!supported.includes(String(source.playbook || ''))) {
  throw new Error('Playbook de inteligência inválido.');
}
return [{ json: {
  missionId: String(source.missionId),
  playbook: String(source.playbook),
  taskId: String(source.taskId),
  actorInput: source.actorInput,
  callbackUrl: String(source.callbackUrl)
} }];

const source = $json;
const input = source.actorInput ?? {};
const requested = Number(input.maxItems ?? 10);
const maxItems = Math.min(500, Math.max(1, Number.isFinite(requested) ? Math.trunc(requested) : 10));

const unique = (values, limit) => [...new Set((values ?? []).map((value) => String(value).trim()).filter(Boolean))].slice(0, limit);

if (source.playbook === 'b2b_prospecting') {
  const keywords = unique(input.keywords, 10);
  const regions = unique(input.regions, 2);
  if (!keywords.length) throw new Error('A prospecção B2B precisa de ao menos um setor ou termo de busca.');
  if (regions.length !== 1) throw new Error('A prospecção B2B precisa de exatamente uma região por missão.');
  const perSearch = Math.max(1, Math.ceil(maxItems / keywords.length));
  return [{ json: {
    ...source,
    requestedMaxItems: maxItems,
    generatedQueries: keywords,
    actorInput: {
      searchStringsArray: keywords,
      locationQuery: regions[0],
      maxCrawledPlacesPerSearch: perSearch,
      language: 'pt-BR',
      skipClosedPlaces: true,
      scrapePlaceDetailPage: false,
      maximumLeadsEnrichmentRecords: 0,
      enableCompetitorAnalysis: false,
      maxCompetitorsToAnalyze: 0,
      scrapeSocialMediaProfiles: {
        facebooks: false,
        instagrams: false,
        youtubes: false,
        tiktoks: false,
        twitters: false
      }
    }
  } }];
}

if (source.playbook === 'market_radar') {
  const keywords = unique(input.keywords, 12);
  const competitors = unique(input.competitors, 10);
  const regions = unique(input.regions, 3);
  const objective = String(input.objective || '').trim();
  const niche = String(input.brand?.niche || '').trim();
  if (!keywords.length && !competitors.length) {
    throw new Error('O Radar precisa de termos de mercado ou concorrentes.');
  }
  const maxQueries = Math.min(5, Math.max(1, Math.ceil(maxItems / 10)));
  const region = regions[0] || 'Brasil';
  const theme = keywords[0] || objective || niche || 'mercado';
  const candidates = [];
  for (const competitor of competitors) {
    try {
      const url = new URL(competitor);
      candidates.push(`site:${url.hostname.replace(/^www\./, '')} ${theme}`);
    } catch {
      candidates.push(`\"${competitor}\" ${theme} ${region}`);
    }
  }
  for (const keyword of keywords) {
    candidates.push(`${keyword} ${niche} ${region}`.replace(/\s+/g, ' ').trim());
  }
  if (!candidates.length && objective) candidates.push(`${objective} ${region}`);
  const queries = [...new Set(candidates.map((value) => value.trim()).filter(Boolean))].slice(0, maxQueries);
  return [{ json: {
    ...source,
    requestedMaxItems: maxItems,
    generatedQueries: queries,
    actorInput: {
      queries: queries.join('\n'),
      maxPagesPerQuery: 1,
      countryCode: 'br',
      searchLanguage: 'pt',
      languageCode: 'pt-BR',
      mobileResults: false,
      includeUnfilteredResults: false,
      saveHtml: false,
      saveHtmlToKeyValueStore: false,
      includeIcons: false,
      maximumLeadsEnrichmentRecords: 0,
      focusOnPaidAds: false,
      aiOverview: { scrapeFullAiOverview: false },
      aiModeSearch: { enableAiMode: false },
      geminiSearch: { enableGemini: false },
      perplexitySearch: { enablePerplexity: false, returnImages: false, returnRelatedQuestions: false },
      chatGptSearch: { enableChatGpt: false },
      copilotSearch: { enableCopilot: false },
      websiteContentScraper: { enable: false }
    }
  } }];
}

return [{ json: { ...source, requestedMaxItems: maxItems } }];

const root = $input.first().json;
if (root?.data?.id) return [{ json: root }];
const chunks = [];
const visited = new Set();
function collect(value) {
  if (!value || typeof value !== 'object' || visited.has(value)) return;
  visited.add(value);
  if (value.type === 'Buffer' && Array.isArray(value.data)) { chunks.push(Buffer.from(value.data)); return; }
  if (Array.isArray(value)) { for (const item of value) collect(item); return; }
  for (const item of Object.values(value)) collect(item);
}
collect(root);
if (!chunks.length) throw new Error('Nenhum buffer foi encontrado na resposta inicial do Apify.');
const raw = Buffer.concat(chunks).toString('utf8');
const runId = raw.match(/\"id\"\s*:\s*\"([^\"]+)\"/)?.[1];
if (!runId) throw new Error('Não foi possível localizar o ID da execução do Apify.');
return [{ json: { data: { id: runId } } }];

const root = $input.first().json;
if (root?.data?.defaultDatasetId) return [{ json: root }];
const chunks = [];
const visited = new Set();
function collect(value) {
  if (!value || typeof value !== 'object' || visited.has(value)) return;
  visited.add(value);
  if (value.type === 'Buffer' && Array.isArray(value.data)) { chunks.push(Buffer.from(value.data)); return; }
  if (Array.isArray(value)) { for (const item of value) collect(item); return; }
  for (const item of Object.values(value)) collect(item);
}
collect(root);
if (!chunks.length) throw new Error('Nenhum buffer foi encontrado na espera do Apify.');
const raw = Buffer.concat(chunks).toString('utf8');
const id = raw.match(/\"id\"\s*:\s*\"([^\"]+)\"/)?.[1] || $('Parse Apify Run Response').first().json.data.id;
const datasetId = raw.match(/\"defaultDatasetId\"\s*:\s*\"([^\"]+)\"/)?.[1];
const status = raw.match(/\"status\"\s*:\s*\"([^\"]+)\"/)?.[1] || '';
if (!datasetId) throw new Error('A execução do Apify não retornou defaultDatasetId.');
return [{ json: { data: { id, defaultDatasetId: datasetId, status } } }];

const all = $input.all();
if (all.length > 1) return all;
const root = all[0]?.json;
if (Array.isArray(root)) return root.map((item) => ({ json: item }));
if (root && typeof root === 'object' && (root.organicResults || root.title || root.placeId)) return all;
const chunks = [];
const visited = new Set();
function collect(value) {
  if (!value || typeof value !== 'object' || visited.has(value)) return;
  visited.add(value);
  if (value.type === 'Buffer' && Array.isArray(value.data)) { chunks.push(Buffer.from(value.data)); return; }
  if (Array.isArray(value)) { for (const item of value) collect(item); return; }
  for (const item of Object.values(value)) collect(item);
}
collect(root);
if (!chunks.length) return all;
const text = Buffer.concat(chunks).toString('utf8');
let start = -1;
let depth = 0;
let inside = false;
let escaped = false;
for (let index = 0; index < text.length; index++) {
  const character = text[index];
  if (inside) {
    if (escaped) escaped = false;
    else if (character === '\\') escaped = true;
    else if (character === '"') inside = false;
    continue;
  }
  if (character === '"') { inside = true; continue; }
  if (character === '[') { if (depth === 0) start = index; depth++; continue; }
  if (character === ']') {
    depth--;
    if (depth === 0 && start !== -1) {
      const candidate = text.slice(start, index + 1);
      try {
        const parsed = JSON.parse(candidate);
        if (Array.isArray(parsed)) return parsed.map((item) => ({ json: item }));
      } catch {}
      start = -1;
    }
  }
}
throw new Error('O dataset do Apify não contém um array JSON válido.');

const source = $('Adapt Playbook Input').first().json;
const incoming = $input.all().map((item) => item.json);
const run = $('Parse Apify Wait Response').first().json.data || {};
const failure = incoming.find((item) => item && typeof item === 'object' && (item.error?.message || Number(item.statusCode || 0) >= 400));
if (failure) {
  const message = failure.error?.message || failure.message || `Apify respondeu ${failure.statusCode}.`;
  return [{ json: { callbackUrl: source.callbackUrl, callbackBody: { status: 'failed', providerRunId: String(run.id || ''), providerDatasetId: String(run.defaultDatasetId || ''), error: String(message).slice(0, 2000) } } }];
}

let items = [];
if (source.playbook === 'b2b_prospecting') {
  const seen = new Set();
  items = incoming.filter((item) => {
    if (!item || typeof item !== 'object' || item.error) return false;
    const key = String(item.placeId || item.url || `${item.title || ''}|${item.street || ''}`).trim().toLowerCase();
    if (!key || seen.has(key)) return false;
    seen.add(key);
    return true;
  }).slice(0, Number(source.requestedMaxItems || 100)).map((item, index) => {
    const phone = String(item.phone || '').trim();
    const website = String(item.website || '').trim();
    const rating = Number(item.totalScore || 0);
    const reviewsCount = Number(item.reviewsCount || 0);
    const qualityScore = (phone ? 30 : 0) + (website ? 25 : 0) + (item.street ? 15 : 0) + (reviewsCount > 0 ? 10 : 0) + (item.categoryName ? 10 : 0) + (rating > 0 ? 10 : 0);
    return { source: 'google_maps', position: index + 1, businessName: String(item.title || ''), category: String(item.categoryName || ''), categories: Array.isArray(item.categories) ? item.categories : [], rating, reviewsCount, address: String(item.street || item.address || ''), city: String(item.city || ''), state: String(item.state || ''), countryCode: String(item.countryCode || ''), phone, website, mapsUrl: String(item.url || ''), contactAvailable: Boolean(phone || website), qualityScore };
  });
}

if (source.playbook === 'market_radar') {
  const generated = Array.isArray(source.generatedQueries) ? source.generatedQueries : [];
  const organic = incoming.flatMap((page, pageIndex) => {
    const query = String(page?.searchQuery?.term || page?.searchQuery || generated[pageIndex] || '');
    const results = Array.isArray(page?.organicResults) ? page.organicResults : [];
    return results.map((result) => ({ ...result, searchQuery: query }));
  });
  const seen = new Set();
  const competitors = (source.actorInput?.competitors || source.generatedQueries || []).map((value) => String(value).toLowerCase());
  items = organic.filter((item) => {
    const key = String(item.url || item.title || '').trim().toLowerCase();
    if (!key || seen.has(key)) return false;
    seen.add(key);
    return true;
  }).slice(0, Number(source.requestedMaxItems || 10)).map((item, index) => {
    const title = String(item.title || '').trim();
    const description = String(item.description || item.snippet || '').trim();
    const url = String(item.url || '').trim();
    let domain = String(item.domain || '').trim();
    if (!domain && url) { try { domain = new URL(url).hostname.replace(/^www\./, ''); } catch {} }
    const haystack = `${title} ${description}`.toLowerCase();
    let signalType = 'mercado';
    if (competitors.some((value) => value && haystack.includes(value.replace(/^https?:\/\//, '').split('/')[0]))) signalType = 'concorrencia';
    else if (/promo[cç][aã]o|desconto|oferta|pre[cç]o|cupom/.test(haystack)) signalType = 'oferta';
    else if (/reclama[cç][aã]o|avalia[cç][aã]o|review|reputa[cç][aã]o/.test(haystack)) signalType = 'reputacao';
    else if (/tend[eê]ncia|crescimento|mercado|dados|pesquisa|futuro/.test(haystack)) signalType = 'tendencia';
    const query = String(item.searchQuery || '');
    const queryWords = query.toLowerCase().split(/\s+/).filter((word) => word.length > 3);
    const matches = queryWords.filter((word) => haystack.includes(word)).length;
    const relevanceScore = Math.min(100, 55 + Math.min(30, matches * 10) + (description ? 10 : 0) + (domain ? 5 : 0));
    return { source: 'google_search', position: index + 1, title, description, url, domain, searchQuery: query, signalType, relevanceScore };
  });
}

if (source.playbook === 'price_monitoring') {
  items = incoming.slice(0, Number(source.requestedMaxItems || 10));
}

if (!items.length) {
  return [{ json: { callbackUrl: source.callbackUrl, callbackBody: { status: 'failed', providerRunId: String(run.id || ''), providerDatasetId: String(run.defaultDatasetId || ''), error: 'O Apify concluiu, mas não retornou registros úteis para este playbook.' } } }];
}
return [{ json: { callbackUrl: source.callbackUrl, callbackBody: { status: 'completed', providerRunId: String(run.id || ''), providerDatasetId: String(run.defaultDatasetId || ''), resultCount: items.length, resultPreview: items.slice(0, 100) } } }];
